export const INITIAL_CHARACTERS = v25Data.characters.map(v25Char => {
  const tactical = TACTICAL_DATA_MAP.get(v25Char.id) || {};
  return {
    ...tactical,
    ...v25Char, // Sobrescribe id, name, franchise, universe, saga, baseTier, baseKiNumeric
    forms: v25Char.forms // Formas canónicas oficiales V25 (ej: Gohan U16 con 3 forms)
  };
});

